def _resume(self, event=None) -> None:
    """从暂停恢复：关闭面板、重启主循环。"""
    if self.paused:
        return
    if self._pause_panel is not None:
        try:
            self._pause_panel.destroy()
        except Exception:
            pass
        self._pause_panel = None
    self.paused = False
    self.rec.record({"event": "resume", "success": True})
    self._schedule(FPS)

